/**
 * Golden Master image picker — admin JS.
 * Opens wp.media for each variant picker and updates the hidden input + preview.
 */
(function () {
	'use strict';

	document.addEventListener('DOMContentLoaded', function () {
		var pickers = document.querySelectorAll('[data-shseq-master-select]');

		pickers.forEach(function (btn) {
			btn.addEventListener('click', function () {
				if (btn.disabled) return;

				var variant = btn.getAttribute('data-shseq-master-select');
				var fieldset = btn.closest('[data-shseq-variant="' + variant + '"]');
				if (!fieldset) return;

				var input   = fieldset.querySelector('[data-shseq-master-field="' + variant + '"]');
				var preview = fieldset.querySelector('[data-shseq-master-preview]');
				var title   = fieldset.getAttribute('data-shseq-picker-title') || 'Select image';
				var button  = fieldset.getAttribute('data-shseq-picker-button') || 'Use this image';

				if (typeof wp === 'undefined' || !wp.media) {
					alert('WordPress media library not available.');
					return;
				}

				var frame = wp.media({
					title: title,
					button: { text: button },
					multiple: false,
					library: { type: 'image' },
				});

				frame.on('select', function () {
					var attachment = frame.state().get('selection').first().toJSON();
					if (!attachment || !attachment.id) return;

					if (input)   input.value = attachment.id;
					if (preview) {
						var img = preview.querySelector('img');
						if (!img) {
							img = document.createElement('img');
							img.alt = '';
							var empty = preview.querySelector('.shseq-master-empty');
							if (empty) empty.remove();
							preview.appendChild(img);
						}
						img.src = attachment.sizes && attachment.sizes.medium
							? attachment.sizes.medium.url
							: attachment.url;
					}
				});

				frame.open();
			});
		});

		// Remove buttons
		var removeBtns = document.querySelectorAll('[data-shseq-master-remove]');
		removeBtns.forEach(function (btn) {
			btn.addEventListener('click', function () {
				if (btn.disabled) return;
				var variant  = btn.getAttribute('data-shseq-master-remove');
				var fieldset = btn.closest('[data-shseq-variant="' + variant + '"]');
				if (!fieldset) return;

				var input   = fieldset.querySelector('[data-shseq-master-field="' + variant + '"]');
				var preview = fieldset.querySelector('[data-shseq-master-preview]');

				if (input)   input.value = '';
				if (preview) {
					var img = preview.querySelector('img');
					if (img) img.remove();
					if (!preview.querySelector('.shseq-master-empty')) {
						var span = document.createElement('span');
						span.className = 'shseq-master-empty';
						span.textContent = preview.getAttribute('data-shseq-empty') || 'No image selected';
						preview.appendChild(span);
					}
				}
			});
		});
	});
}());
